        .card-icon {
            width: 24px;
            height: 24px;
            color: var(--primary);
        }

        .card-title {
            font-size: 1.1rem;
            font-weight: 600;
            color: var(--text-main);
        }

        .card-body {
            padding: 1.5rem;
            font-size: 1.05rem;
